-- Explicit compatibility patch for a database missing the merged SOP/training JPA schema.
-- Outside automatic Flyway and training-patch locations. Apply only after checking the target schema and backing it up.
-- Existing SOP columns and audit timestamps are not changed. Required defaults match the entities.
create table sop_assignment (id bigint generated by default as identity, assigned_by uuid not null, audience text not null, created_at timestamp(6) with time zone not null, days_to_complete integer not null, deadline date not null, effective_date date not null, mandatory boolean not null, mode varchar(255) not null check (mode in ('PORTAL','IMMEDIATE')), pass_mark integer not null, sop_document_id bigint not null, staff_count integer not null, primary key (id));
create table sop_course_feedback (id bigint generated by default as identity, comment text, created_at timestamp(6) with time zone not null, rating integer not null, sop_document_id bigint not null, staff_id uuid not null, updated_at timestamp(6) with time zone not null, primary key (id));
alter table if exists sop_document add column archived_at timestamp(6) with time zone;
alter table if exists sop_document add column course_id bigint;
alter table if exists sop_document add column course_status varchar(20) default 'LIVE' not null check (course_status in ('LIVE','DRAFT','SUPERSEDED','ARCHIVED'));
alter table if exists sop_document add column duration_minutes integer;
alter table if exists sop_document add column pass_mark integer default 70 not null;
alter table if exists sop_document add column previous_version_id bigint;
alter table if exists sop_document add column version_no integer default 1 not null;
alter table if exists sop_document add column visibility varchar(255) check (visibility in ('PRIVATE','OPEN'));
create table sop_enrollment (id bigint generated by default as identity, assigned_at timestamp(6) with time zone not null, assignment_id bigint, completed_at timestamp(6) with time zone, days_to_complete integer, deadline date, duration_minutes integer, effective_date date not null, final_score integer, mandatory boolean not null, mode varchar(255) not null check (mode in ('PORTAL','IMMEDIATE')), pass_mark integer not null, sop_document_id bigint not null, staff_id uuid not null, started_at timestamp(6) with time zone, status varchar(255) not null check (status in ('NOT_STARTED','IN_PROGRESS','COMPLETED','WITHDRAWN')), updated_at timestamp(6) with time zone not null, primary key (id));
create table sop_material_review_event (id bigint generated by default as identity, action varchar(20) not null, actor_id uuid, created_at timestamp(6) with time zone not null, detail text, sop_module_id bigint not null, primary key (id));
create table sop_quiz_attempt (id bigint generated by default as identity, answers text, attempted_at timestamp(6) with time zone not null, correct integer not null, enrollment_id bigint not null, passed boolean not null, score integer not null, sop_module_id bigint not null, staff_id uuid not null, total integer not null, primary key (id));
alter table if exists sop_quiz_question add column difficulty varchar(255) check (difficulty in ('EASY','MEDIUM','HARD'));
create table sop_quiz_review_event (id bigint generated by default as identity, action varchar(255) not null check (action in ('APPROVED','REJECTED','REGENERATED','EDITED','COPIED')), actor_id uuid, created_at timestamp(6) with time zone not null, detail text, sop_module_id bigint not null, primary key (id));
create table trainer_access_grant (staff_id uuid not null, end_date date, granted_at timestamp(6) with time zone not null, granted_by uuid not null, lapsed_at timestamp(6) with time zone, revoked_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, primary key (staff_id));
create table training_audit_log (id bigint generated by default as identity, action varchar(60) not null, actor_id uuid, created_at timestamp(6) with time zone not null, detail text, reason text, target_id varchar(64) not null, target_type varchar(30) not null, primary key (id));
create table training_job_run (id bigint generated by default as identity, finished_at timestamp(6) with time zone not null, job_name varchar(60) not null, outcome text, run_date date not null, started_at timestamp(6) with time zone not null, primary key (id));
alter table if exists sop_course_feedback add constraint UKkj4avjikcu3bwrf25vbhguwgg unique (sop_document_id, staff_id);
alter table if exists sop_enrollment add constraint UK8cfd13get2xmw9g0uyjvifsfi unique (sop_document_id, staff_id);
create index idx_training_audit_target on training_audit_log (target_type, target_id);
alter table if exists training_job_run add constraint uk_training_job_run_day unique (job_name, run_date);
